using System.Buffers.Binary;
using System.Text;
using MeowFilm.Media;

namespace MeowFilm.Windows.Tests;

// Actual current audio AVIO lease adapter and decoder. Generated bytes are never
// materialized as an input path; owner cases explicitly use a no-device sink.
public static class AudioReadLeaseTests
{
    public static IEnumerable<TestCase> Cases()
    {
        foreach (string invalid in new[] { "unreadable", "unseekable", "writable", "negative",
                     "unbounded", "extent-mismatch", "null-stream", "throwing-getter" })
            yield return new("audio.read-lease.reject-" + invalid, () => InvalidLease(invalid));
        yield return new("audio.read-lease.zero-extent-is-not-unknown", EmptyLease);
        yield return new("audio.read-lease.precancelled-and-prerevoked-release", PreflightLifetime);
        yield return new("audio.read-lease.byte-at-a-time-exact-seek-eof", ExactBytes);
        yield return new("audio.read-lease.int-max-request-and-virtual-extent-bounded", BoundedBytes);
        foreach (string bad in new[] { "outside", "throws", "wrong-offset" })
            yield return new("audio.read-lease.seek-fails-closed-" + bad, () => InvalidSeek(bad));
        foreach (string bad in new[] { "truncated", "changed", "throws", "invalid-count" })
            yield return new("audio.read-lease.read-fails-closed-" + bad, () => InvalidRead(bad));
        yield return new("audio.read-lease.revocation-during-read-copies-no-bytes", RevokeDuringRead);
        foreach (bool revoke in new[] { false, true })
            yield return new("audio.read-lease.token-ignoring-read-" + (revoke ? "revoke" : "cancel") + "-closes",
                () => BlockedRead(revoke));
        foreach (var (name, content) in new[]
        {
            ("m3u-disguised-wav", "#EXTM3U\n#EXTINF:1,x\nhttps://media.invalid/secret.wav"),
            ("hls-audio-wav", "\uFEFF \n#EXTM3U\n#EXT-X-KEY:METHOD=AES-128,URI=\"https://media.invalid/key\""),
            ("dash-video-mp4", "<?xml version=\"1.0\"?><MPD><BaseURL>https://media.invalid/</BaseURL></MPD>"),
            ("smooth-octet-stream", "<SmoothStreamingMedia><StreamIndex Url=\"https://media.invalid/\"/></SmoothStreamingMedia>"),
            ("pls-filename-mp3", "[playlist]\nFile1=https://media.invalid/file.wav"),
            ("xspf-audio-flac", "<playlist><trackList><track><location>https://media.invalid/</location></track></trackList></playlist>"),
            ("http-mime-envelope", "HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\n\r\n#EXTM3U\nhttps://media.invalid/"),
            ("html", "<html><audio src=\"https://media.invalid/x.wav\"></audio></html>")
        })
            yield return new("audio.read-lease.native-rejects-playlist-" + name, () => Poison(content));
        yield return new("audio.read-lease.dummy-natural-end-releases-before-reentrant-queue",
            () => NativeMediaFixtures.Sta(ReentrantQueue));
        foreach (bool seek in new[] { false, true })
            yield return new("audio.read-lease.dummy-" + (seek ? "seek" : "read") + "-failure-retires-before-failed",
                () => NativeMediaFixtures.Sta(() => NativeFailure(seek)));
        yield return new("audio.read-lease.dummy-self-revoking-release-is-natural-end",
            () => NativeMediaFixtures.Sta(SelfRevokingEnd));
        yield return new("audio.read-lease.dummy-self-revoking-release-preserves-opening-cancel",
            () => NativeMediaFixtures.Sta(SelfRevokingCancel));
    }

    private static Task InvalidLease(string invalid)
    {
        var lease = new Lease();
        switch (invalid)
        {
            case "unreadable": lease.Stream.Readable = false; break;
            case "unseekable": lease.Stream.Seekable = false; break;
            case "writable": lease.Stream.Writable = true; break;
            case "negative": lease.DeclaredLength = -1; break;
            case "unbounded": lease.DeclaredLength = long.MaxValue; break;
            case "extent-mismatch": lease.DeclaredLength--; break;
            case "null-stream": lease.NullContent = true; break;
            case "throwing-getter": lease.ThrowContent = true; break;
        }
        using (var input = new AudioDecoderInput(lease, default))
            ErrorSync(() => input.Open(), PlaybackError.InvalidReadLease);
        Released(lease);
        Check(lease.Stream.ReadCalls == 0, "invalid lease reads no bytes");
        return Task.CompletedTask;
    }

    private static async Task EmptyLease()
    {
        var lease = new Lease([]);
        await Error(async () =>
        {
            using var decoder = await AudioDecoder.OpenReadAsync(lease, default);
        }, PlaybackError.ReadFormatUnsupported);
        Released(lease);
        Check(lease.Stream.ReadCalls == 0, "zero extent is exact EOF, not an unbounded stream");
    }

    private static async Task PreflightLifetime()
    {
        var cancelled = new Lease();
        using var caller = new CancellationTokenSource(); caller.Cancel();
        using (var input = new AudioDecoderInput(cancelled, caller.Token))
            await Cancelled(() => Task.Run(() => input.Open()));
        Released(cancelled);
        var revoked = new Lease(); revoked.Revoke();
        using (var input = new AudioDecoderInput(revoked, default))
            ErrorSync(() => input.Open(), PlaybackError.ReadRevoked);
        Released(revoked);
        Check(cancelled.Stream.ReadCalls == 0 && revoked.Stream.ReadCalls == 0, "no bytes after prior cancellation/revocation");
    }

    private static Task ExactBytes()
    {
        var lease = new Lease(seconds: .02);
        lease.Stream.Chunk = 1;
        using (var input = new AudioDecoderInput(lease, default))
        {
            input.Open();
            Check(input.Length == lease.Length && input.CanSeek && lease.Stream.ReturnedBytes == 0,
                "current AVIO open validates metadata without a whole-file or prefix prefetch");
            var bytes = new byte[65536];
            for (long offset = 0; offset < lease.Length; offset++)
                Check(Read(input, bytes, int.MaxValue) == 1 && bytes[0] == lease.Stream.ByteAt(offset),
                    "exact granted byte sequence");
            Check(Read(input, bytes, 1) == 0 && Read(input, bytes, 1) == 0, "stable exact EOF");
            Check(input.Seek(17, 0) == 17 && Read(input, bytes, 1) == 1 && bytes[0] == lease.Stream.ByteAt(17),
                "backward absolute seek");
            Check(input.Seek(2, 1) == 20 && Read(input, bytes, 1) == 1 && bytes[0] == lease.Stream.ByteAt(20),
                "relative seek follows delivered bytes");
            Check(input.Seek(-1, 2) == lease.Length - 1 && Read(input, bytes, 1) == 1 &&
                bytes[0] == lease.Stream.ByteAt(lease.Length - 1), "tail seek");
            Check(input.Seek(lease.Length, 0) == lease.Length && Read(input, bytes, 1) == 0 &&
                input.LastErrorCode is null, "seek exactly to EOF is not a failure");
            Check(lease.Stream.MaximumRequest <= 65536 && lease.DisposeCalls == 0, "lease retained and read bound fixed");
            input.Dispose(); input.Dispose();
        }
        Released(lease);
        return Task.CompletedTask;
    }

    private static Task BoundedBytes()
    {
        var lease = new Lease([], (1L << 40) + 17);
        using (var input = new AudioDecoderInput(lease, default))
        {
            input.Open();
            Check(lease.Stream.ReadCalls == 0 && lease.Stream.ReturnedBytes == 0, "no prefetch during adapter open");
            var bytes = new byte[65536];
            Check(Read(input, bytes, int.MaxValue) == 65536 &&
                bytes.Select((value, offset) => value == lease.Stream.ByteAt(offset)).All(value => value),
                "int max native request is bounded and byte exact");
            Check(input.Seek(lease.Length - 7, 0) == lease.Length - 7 && Read(input, bytes, int.MaxValue) == 7 &&
                bytes.Take(7).SequenceEqual(Enumerable.Range(0, 7).Select(i => lease.Stream.ByteAt(lease.Length - 7 + i))),
                "large virtual extent reads only the requested tail");
            Check(lease.Stream.ReturnedBytes == 65536 + 7 && lease.Stream.MaximumRequest <= 65536,
                "no full-file cache or unbounded allocation");
        }
        Released(lease);
        return Task.CompletedTask;
    }

    private static Task InvalidSeek(string bad)
    {
        var lease = new Lease();
        using (var input = new AudioDecoderInput(lease, default))
        {
            input.Open();
            lease.Stream.ThrowSeek = bad == "throws";
            lease.Stream.WrongSeek = bad == "wrong-offset";
            CallbackError(() => input.Seek(bad == "outside" ? input.Length + 1 : 100, 0), input,
                PlaybackError.ReadSeekFailed);
            ErrorSync(() => Read(input, new byte[1], 1), PlaybackError.ReadSeekFailed);
        }
        Released(lease);
        return Task.CompletedTask;
    }

    private static Task InvalidRead(string bad)
    {
        var lease = new Lease();
        using (var input = new AudioDecoderInput(lease, default))
        {
            input.Open();
            switch (bad)
            {
                case "truncated": lease.Stream.EofAt = 0; break;
                case "changed": lease.Stream.LengthDelta = 1; break;
                case "throws": lease.Stream.ThrowRead = true; break;
                case "invalid-count": lease.Stream.InvalidCount = true; break;
            }
            string code = bad switch
            {
                "changed" => PlaybackError.ReadChanged, "throws" => PlaybackError.ReadFailed,
                _ => PlaybackError.ReadTruncated
            };
            var bytes = Enumerable.Repeat((byte)0xa5, 32).ToArray();
            CallbackError(() => Read(input, bytes, bytes.Length), input, code);
            Check(bytes.All(value => value == 0xa5), "failed read copies no bytes");
            ErrorSync(() => input.Seek(0, 0), code);
        }
        Released(lease);
        return Task.CompletedTask;
    }

    private static Task RevokeDuringRead()
    {
        var lease = new Lease();
        using (var input = new AudioDecoderInput(lease, default))
        {
            input.Open();
            lease.Stream.AfterRead = lease.Revoke;
            var bytes = Enumerable.Repeat((byte)0xa5, 128).ToArray();
            CallbackError(() => Read(input, bytes, bytes.Length), input, PlaybackError.ReadRevoked);
            Check(bytes.All(value => value == 0xa5), "no copy after authorization is lost during byte return");
        }
        Released(lease);
        return Task.CompletedTask;
    }

    private static async Task BlockedRead(bool revoke)
    {
        var lease = new Lease();
        lease.Stream.BlockAt = 0; lease.Stream.UnblockOnlyOnDispose = true;
        using var caller = new CancellationTokenSource();
        using var input = new AudioDecoderInput(lease, caller.Token);
        input.Open();
        var bytes = Enumerable.Repeat((byte)0xa5, 128).ToArray();
        Task reading = Task.Run(() => Read(input, bytes, bytes.Length));
        try
        {
            await Task.WhenAny(lease.Stream.ReadBlocked.Task, reading).WaitAsync(TimeSpan.FromSeconds(5));
            Check(lease.Stream.ReadBlocked.Task.IsCompletedSuccessfully && !reading.IsCompleted, "actual token-ignoring read blocked");
            if (revoke) lease.Revoke();
            else caller.Cancel();
            await lease.Released.Task.WaitAsync(TimeSpan.FromSeconds(3));
            try { await reading.WaitAsync(TimeSpan.FromSeconds(3)); throw new InvalidOperationException("Blocked read unexpectedly succeeded"); }
            catch (ObjectDisposedException) { /* The raw AVIO adapter observes the physically closed stream. */ }
            Check(bytes.All(value => value == 0xa5) && input.LastErrorCode == (revoke ? PlaybackError.ReadRevoked : null),
                "physical close publishes no bytes and preserves cancellation/revocation classification");
            input.Dispose();
            Released(lease);
        }
        finally
        {
            input.Cancel();
            try { await reading.WaitAsync(TimeSpan.FromSeconds(3)); }
            catch (ObjectDisposedException) { }
        }
    }

    private static async Task Poison(string content)
    {
        var lease = new Lease(Encoding.UTF8.GetBytes(content));
        await Error(async () =>
        {
            using var decoder = await AudioDecoder.OpenReadAsync(lease, default);
        }, PlaybackError.ReadFormatUnsupported);
        Released(lease);
    }

    private static async Task ReentrantQueue()
    {
        await using var player = new NativeAudioPlayback(audioOutput: NativeAudioOutput.Dummy);
        var first = new Lease(seconds: .7); var second = new Lease();
        int ended = 0, failed = 0;
        Task? next = null;
        var queued = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        player.Failed += (_, _) => failed++;
        player.Ended += (_, _) =>
        {
            ended++;
            Released(first);
            Check(!player.HasMedia, "old native input retired before the queue callback");
            next = player.OpenReadAsync("music", "queued", second, "generated WAV");
            queued.TrySetResult();
        };
        await player.OpenReadAsync("music", "first", first, "generated WAV");
        await queued.Task.WaitAsync(TimeSpan.FromSeconds(8));
        await next!.WaitAsync(TimeSpan.FromSeconds(8));
        Check(ended == 1 && failed == 0 && player.HasMedia && player.IsPlaying &&
            player.Identity == "queued" && second.DisposeCalls == 0, "reentrant queue owns a distinct healthy native input");
        await player.StopAsync();
        Released(first); Released(second);
    }

    private static async Task NativeFailure(bool seek)
    {
        await using var player = new NativeAudioPlayback(audioOutput: NativeAudioOutput.Dummy);
        var lease = new Lease(seconds: 600);
        int ended = 0, failed = 0;
        var retired = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        player.Ended += (_, _) => ended++;
        player.Failed += (_, _) =>
        {
            failed++;
            Released(lease);
            Check(!player.HasMedia, "failed native input retired before notification");
            retired.TrySetResult();
        };
        await player.OpenReadAsync("music", "failure", lease, "generated WAV");
        lease.Stream.ThrowSeek = seek;
        lease.Stream.ThrowRead = !seek;
        string code = seek ? PlaybackError.ReadSeekFailed : PlaybackError.ReadFailed;
        await Error(() => player.SeekAsync(500), code);
        await retired.Task.WaitAsync(TimeSpan.FromSeconds(8));
        Check(failed == 1 && ended == 0 && !player.HasMedia && player.LastErrorCode == code,
            "actual read/seek failure cannot become natural EOF or a successful requested position");
        Released(lease);
    }

    private static async Task SelfRevokingEnd()
    {
        await using var player = new NativeAudioPlayback(audioOutput: NativeAudioOutput.Dummy);
        var lease = new Lease(seconds: .7) { RevokeOnDispose = true };
        int ended = 0, failed = 0;
        var finished = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        player.Failed += (_, _) => failed++;
        player.Ended += (_, _) =>
        {
            ended++;
            Released(lease);
            Check(!player.HasMedia, "actual input retired before natural end");
            finished.TrySetResult();
        };
        await player.OpenReadAsync("music", "self-revoking", lease, "generated WAV");
        await finished.Task.WaitAsync(TimeSpan.FromSeconds(8));
        Check(ended == 1 && failed == 0 && player.LastErrorCode is null && !player.HasMedia,
            "owner release revocation does not turn natural EOF into Failed");
        Released(lease);
    }

    private static async Task SelfRevokingCancel()
    {
        await using var player = new NativeAudioPlayback(audioOutput: NativeAudioOutput.Dummy);
        using var caller = new CancellationTokenSource();
        var lease = new Lease { RevokeOnDispose = true };
        lease.Stream.BlockAt = 0; lease.Stream.UnblockOnlyOnDispose = true;
        int failed = 0, ended = 0;
        player.Failed += (_, _) => failed++;
        player.Ended += (_, _) => ended++;
        Task opening = player.OpenReadAsync("music", "self-revoking-cancel", lease, "generated WAV", caller.Token);
        try
        {
            await Task.WhenAny(lease.Stream.ReadBlocked.Task, opening).WaitAsync(TimeSpan.FromSeconds(5));
            Check(lease.Stream.ReadBlocked.Task.IsCompletedSuccessfully && !opening.IsCompleted, "native opening read blocked");
            caller.Cancel();
            await Cancelled(() => opening);
            Released(lease);
            Check(failed == 0 && ended == 0 && !player.HasMedia && player.LastErrorCode is null,
                "caller cancellation is not a revoked-content failure");
        }
        finally
        {
            caller.Cancel();
            try { await opening.WaitAsync(TimeSpan.FromSeconds(3)); }
            catch (OperationCanceledException) { }
        }
    }

    private static unsafe int Read(AudioDecoderInput input, byte[] bytes, int count)
    {
        fixed (byte* pointer = bytes) return input.Read((IntPtr)pointer, count);
    }

    private static void Check(bool condition, string stage)
    {
        if (!condition) throw new InvalidOperationException("Read lease assertion: " + stage);
    }

    private static void Released(Lease lease) =>
        Check(lease.DisposeCalls == 1 && lease.Stream.CloseCalls == 1 && lease.ReleaseComplete,
            "exactly one actual lease/stream release");

    private static void ErrorSync(Action action, string code)
    {
        try { action(); }
        catch (PlaybackException error)
        {
            Check(error.Code == code && error.Message == code && error.InnerException is null, "fixed error " + code);
            return;
        }
        throw new InvalidOperationException("Expected fixed error " + code);
    }

    private static void CallbackError(Action action, AudioDecoderInput input, string code)
    {
        try { action(); }
        catch (PlaybackException error)
        {
            Check(error.Code == code && error.Message == code && error.InnerException is null &&
                input.LastErrorCode == code, "fixed callback error " + code);
            return;
        }
        catch (IOException)
        {
            Check(input.LastErrorCode == code, "raw stream exception classified at the current AVIO boundary");
            return;
        }
        throw new InvalidOperationException("Expected callback failure " + code);
    }

    private static async Task Error(Func<Task> action, string code)
    {
        try { await action().WaitAsync(TimeSpan.FromSeconds(10)); }
        catch (PlaybackException error)
        {
            Check(error.Code == code && error.Message == code && error.InnerException is null, "fixed error " + code);
            return;
        }
        throw new InvalidOperationException("Expected fixed error " + code);
    }

    private static async Task Cancelled(Func<Task> action)
    {
        try { await action().WaitAsync(TimeSpan.FromSeconds(10)); }
        catch (OperationCanceledException) { return; }
        throw new InvalidOperationException("Expected cancellation");
    }

    private sealed class Lease : INativeMediaReadLease
    {
        private readonly CancellationTokenSource revoked = new();
        internal readonly GeneratedStream Stream;
        internal long DeclaredLength;
        internal bool NullContent, ThrowContent, RevokeOnDispose;
        internal int DisposeCalls;
        internal volatile bool ReleaseComplete;
        internal readonly TaskCompletionSource Released = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Stream Content => ThrowContent ? throw new IOException("private-path-cookie-canary")
            : NullContent ? null! : Stream;
        public long Length => DeclaredLength;
        public CancellationToken Revoked => revoked.Token;
        internal Lease(double seconds = 60) : this(WaveHeader(seconds), (long)(48000 * seconds) * 2 + 44) { }
        internal Lease(byte[] bytes) : this(bytes, bytes.Length) { }
        internal Lease(byte[] prefix, long length)
        { DeclaredLength = length; Stream = new(prefix, length, () => revoked.IsCancellationRequested); }
        internal void Revoke() => revoked.Cancel();
        public ValueTask DisposeAsync()
        {
            Interlocked.Increment(ref DisposeCalls);
            if (RevokeOnDispose) revoked.Cancel();
            Stream.Dispose();
            ReleaseComplete = true; Released.TrySetResult();
            return ValueTask.CompletedTask;
        }
        private static byte[] WaveHeader(double seconds)
        {
            int bytes = checked((int)(48000 * seconds) * 2);
            var header = new byte[44];
            "RIFF"u8.CopyTo(header); BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(4), bytes + 36);
            "WAVEfmt "u8.CopyTo(header.AsSpan(8)); BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(16), 16);
            BinaryPrimitives.WriteInt16LittleEndian(header.AsSpan(20), 1);
            BinaryPrimitives.WriteInt16LittleEndian(header.AsSpan(22), 1);
            BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(24), 48000);
            BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(28), 96000);
            BinaryPrimitives.WriteInt16LittleEndian(header.AsSpan(32), 2);
            BinaryPrimitives.WriteInt16LittleEndian(header.AsSpan(34), 16);
            "data"u8.CopyTo(header.AsSpan(36)); BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(40), bytes);
            return header;
        }
    }

    private sealed class GeneratedStream(byte[] prefix, long length, Func<bool> revoked) : Stream
    {
        private long position;
        private volatile bool closed;
        private readonly TaskCompletionSource close = new(TaskCreationOptions.RunContinuationsAsynchronously);
        internal readonly TaskCompletionSource ReadBlocked = new(TaskCreationOptions.RunContinuationsAsynchronously);
        internal bool Readable = true, Seekable = true, Writable, ThrowSeek, WrongSeek, ThrowRead, InvalidCount, UnblockOnlyOnDispose;
        internal long LengthDelta, EofAt = long.MaxValue, BlockAt = long.MaxValue, ReturnedBytes;
        internal int Chunk = int.MaxValue, MaximumRequest, ReadCalls, CloseCalls;
        internal Action? AfterRead;
        public override bool CanRead => Readable && !closed;
        public override bool CanSeek => Seekable && !closed;
        public override bool CanWrite => Writable;
        public override long Length { get { Authorized(); return length + LengthDelta; } }
        public override long Position { get { Authorized(); return position; } set => Seek(value, SeekOrigin.Begin); }
        private void Authorized()
        {
            if (closed || revoked()) throw new ObjectDisposedException("authorized-stream");
        }
        internal byte ByteAt(long offset) => offset < prefix.Length ? prefix[(int)offset] : (byte)((offset - 44) * 17 + 11);
        public override async ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            Authorized(); cancellationToken.ThrowIfCancellationRequested();
            Interlocked.Increment(ref ReadCalls);
            MaximumRequest = Math.Max(MaximumRequest, buffer.Length);
            if (position >= BlockAt)
            {
                ReadBlocked.TrySetResult();
                if (UnblockOnlyOnDispose) await close.Task.ConfigureAwait(false);
                else await close.Task.WaitAsync(cancellationToken).ConfigureAwait(false);
                Authorized();
            }
            if (ThrowRead) throw new IOException("private-path-token-read-canary");
            if (InvalidCount) return buffer.Length + 1;
            if (position >= EofAt) return 0;
            int count = (int)Math.Min(Math.Min(Chunk, buffer.Length), length - position);
            for (int i = 0; i < count; i++) buffer.Span[i] = ByteAt(position + i);
            position += count;
            Interlocked.Add(ref ReturnedBytes, count);
            AfterRead?.Invoke();
            return count;
        }
        public override long Seek(long offset, SeekOrigin origin)
        {
            Authorized();
            if (ThrowSeek) throw new IOException("private-seek-canary");
            Check(origin == SeekOrigin.Begin && offset >= 0 && offset <= length, "bounded direct stream seek");
            position = offset;
            return WrongSeek ? offset + 1 : offset;
        }
        public override int Read(byte[] buffer, int offset, int count) => throw new InvalidOperationException("No synchronous stream read expected");
        public override void Flush() => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        protected override void Dispose(bool disposing)
        {
            if (disposing) { Interlocked.Increment(ref CloseCalls); closed = true; close.TrySetResult(); }
            base.Dispose(disposing);
        }
    }
}
